import { Button, Loader, Paper, Text, Textarea } from '@mantine/core';
import { IconArrowRight, IconSend, IconSparkles } from '@tabler/icons-react';
import { useMutation } from '@tanstack/react-query';
import { useEffect, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { api } from '../api/client';
import type { ChatTurn, ReportDraft } from '../api/types';
import { errorMessage, humanize } from '../lib/format';
import { useAiAvailable } from '../lib/useAiAvailable';
import classes from './AiCopilot.module.css';

/** "Generated by …" line: AI output is always labelled as such and to be checked. */
function Provenance({ model }: { model: string }) {
  return (
    <Text size="xs" c="dimmed" mt="sm">
      Generated by Google Gemini ({model}). Check it before acting on it.
    </Text>
  );
}

// ----- fix suggestions on the incident page ---------------------------------------------------------------------

/** Support staff: suggested fix steps for an open incident, grounded in similar resolved incidents. */
export function AiFixSuggestion({ incidentId }: { incidentId: number }) {
  const available = useAiAvailable();
  const suggest = useMutation({ mutationFn: () => api.incidents.aiSuggestion(incidentId) });
  if (!available) return null;
  const s = suggest.data;

  return (
    <Paper withBorder p="lg">
      <div className={classes.head}>
        <IconSparkles size={18} stroke={1.6} />
        <Text fw={700}>AI fix suggestion</Text>
      </div>
      {!s && (
        <>
          <Text size="sm" c="dimmed" mt={6} mb="sm">
            Troubleshooting steps drafted from similar incidents that were already resolved.
          </Text>
          <Button
            variant="outline"
            leftSection={<IconSparkles size={16} />}
            loading={suggest.isPending}
            onClick={() => suggest.mutate()}
          >
            Suggest a fix
          </Button>
          {suggest.isPending && (
            <Text size="xs" c="dimmed" mt="xs">
              Asking Gemini, this takes a few seconds…
            </Text>
          )}
          {suggest.error && (
            <Text size="sm" c="var(--app-stamp)" mt="sm">
              {errorMessage(suggest.error)}
            </Text>
          )}
        </>
      )}
      {s && (
        <>
          <Text size="sm" mt={8}>
            {s.summary}
          </Text>
          <ol className={classes.steps}>
            {s.steps.map((step) => (
              <li key={step}>{step}</li>
            ))}
          </ol>
          {s.likelyCause && (
            <div className={classes.cause}>
              <span className={classes.label}>Likely cause</span>
              <Text size="sm">{s.likelyCause}</Text>
            </div>
          )}
          {s.basedOn.length > 0 && (
            <div className={classes.cause}>
              <span className={classes.label}>Based on</span>
              <div className={classes.refs}>
                {s.basedOn.map((n) => (
                  <Link key={n} to={`/incidents?q=${encodeURIComponent(n)}&scope=ALL`} className={classes.ref}>
                    {n}
                  </Link>
                ))}
              </div>
            </div>
          )}
          <Provenance model={s.model} />
          <Button variant="subtle" size="xs" mt="xs" loading={suggest.isPending} onClick={() => suggest.mutate()}>
            Ask again
          </Button>
        </>
      )}
    </Paper>
  );
}

// ----- chat-based reporting -------------------------------------------------------------------------------------

const OPENING = "Hi! Tell me what's going wrong, in your own words. I'll ask a couple of questions and fill in the report for you.";

/**
 * Employees: describe the problem in a chat; the assistant asks follow-ups and prepares the report. The draft only
 * fills in the form: the employee reviews and submits it themselves.
 */
export function AiReportChat({ onUseDraft }: { onUseDraft: (draft: ReportDraft) => void }) {
  const [turns, setTurns] = useState<ChatTurn[]>([]);
  const [text, setText] = useState('');
  const [draft, setDraft] = useState<ReportDraft | null>(null);
  const [model, setModel] = useState<string | null>(null);
  const end = useRef<HTMLDivElement>(null);

  const chat = useMutation({
    mutationFn: (messages: ChatTurn[]) => api.ai.reportChat(messages),
    onSuccess: (reply, messages) => {
      setTurns([...messages, { role: 'assistant', text: reply.reply }]);
      setModel(reply.model);
      if (reply.ready && reply.draft) setDraft(reply.draft);
    },
  });

  useEffect(() => {
    end.current?.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
  }, [turns, chat.isPending]);

  const send = () => {
    const message = text.trim();
    if (!message || chat.isPending) return;
    const next: ChatTurn[] = [...turns, { role: 'user', text: message }];
    setTurns(next);
    setText('');
    chat.mutate(next);
  };

  return (
    <Paper withBorder p="lg">
      <div className={classes.chat} aria-live="polite">
        <div className={classes.bubble} data-from="assistant">
          {OPENING}
        </div>
        {turns.map((t, index) => (
          <div key={index} className={classes.bubble} data-from={t.role}>
            {t.text}
          </div>
        ))}
        {chat.isPending && (
          <div className={classes.bubble} data-from="assistant">
            <Loader size="xs" type="dots" />
          </div>
        )}
        {chat.error && (
          <Text size="sm" c="var(--app-stamp)">
            {errorMessage(chat.error)}
          </Text>
        )}
        <div ref={end} />
      </div>

      {draft && (
        <div className={classes.draft}>
          <span className={classes.label}>Prepared report</span>
          <Text fw={700} mt={4}>
            {draft.title}
          </Text>
          <Text size="sm" c="dimmed">
            {[draft.serviceName, draft.categoryName, `${humanize(draft.impact)} impact`, `${humanize(draft.urgency)} urgency`,
              `${draft.affectedUsers} ${draft.affectedUsers === 1 ? 'user' : 'users'}`]
              .filter(Boolean)
              .join(' · ')}
          </Text>
          {!draft.serviceId && (
            <Text size="sm" c="var(--app-stamp)" mt={4}>
              No matching IT service: choose the closest one in the form.
            </Text>
          )}
          <Button mt="sm" rightSection={<IconArrowRight size={16} />} onClick={() => onUseDraft(draft)}>
            Review this report
          </Button>
        </div>
      )}

      <div className={classes.composer}>
        <Textarea
          aria-label="Message to the assistant"
          placeholder={draft ? 'Add anything else, or review the report above' : 'Describe the problem…'}
          autosize
          minRows={1}
          maxRows={5}
          value={text}
          onChange={(e) => setText(e.currentTarget.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
              e.preventDefault();
              send();
            }
          }}
          style={{ flex: 1 }}
        />
        <Button onClick={send} disabled={!text.trim()} loading={chat.isPending} aria-label="Send">
          <IconSend size={16} />
        </Button>
      </div>
      {model && <Provenance model={model} />}
    </Paper>
  );
}
